"""Full priority-list data definitions, public helpers and implementation."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='우선순위 큐 · 이중 연결 리스트 · 불변식',
                     sections=sections, questions=questions))


add('include/linux/plist_types.h', 'Plist 타입 전체: 객체 하나에 두 연결 노드',
    '우선순위별 대표 연결과 모든 객체의 연결을 함께 유지하는 최소 자료형 정의입니다.',
    'head는 전체 노드 연결의 기준점만 가지고 node는 정수 우선순위와 두 list_head를 가집니다.',
    '두 연결 멤버의 역할을 구분해야 합니다. 이 파일 자체에는 초기화·잠금·삽입 알고리즘이 없습니다.',
    [('전체 파일', 'GPL SPDX, include guard, linux/types.h, plist_head와 plist_node의 정의, endif가 전부입니다. list_head 자료형을 포함 문맥에서 사용할 수 있도록 의존 헤더를 포함합니다.'),
     ('헤드와 객체', 'plist_head는 node_list 하나입니다. plist_node는 int prio, prio_list, node_list 순서입니다. 전체 객체는 node_list로 연결되고 서로 다른 우선순위의 대표들은 prio_list로 연결됩니다. 헤드에 별도 prio_list가 없으므로 대표 링의 시작점은 첫 실제 노드에서 얻습니다.'),
     ('CS 연결', '객체에 링크를 넣는 침입형 자료구조, 하나의 객체를 두 인덱스에 참여시키는 설계, sentinel 기반 전체 목록과 별도 대표 링을 학습합니다. 두 링크가 있다고 객체를 두 번 할당하거나 내용이 복제되는 것은 아닙니다.')],
    [('plist_head에도 prio_list가 있는가?', '없다. node_list만 있다', '있다. 두 링의 독립 헤드를 모두 갖는다', '타입 선언에서 head는 하나의 list_head만 가집니다. 우선순위 대표 링은 실제 노드를 통해 접근합니다.'),
     ('plist_node의 두 연결 멤버는 같은 역할인가?', '아니다. 대표 우선순위 연결과 전체 노드 연결이다', '그렇다. 같은 정보를 단순 복사한다', '동일 우선순위 객체 전체를 대표 링에 넣지 않으므로 두 연결의 구성원이 다를 수 있습니다.')])

add('include/linux/plist.h', 'Plist 공개 헤더 전체: 숫자 순서와 동일 우선순위 FIFO',
    '우선순위 정렬과 같은 우선순위의 FIFO 순서를 유지하는 리스트 API입니다.',
    '숫자가 작을수록 높은 우선순위입니다. 서로 다른 우선순위 대표만 탐색해 삽입 위치를 찾고 전체 객체 순서는 node_list에 유지합니다.',
    '호출자가 잠금과 객체 수명을 관리합니다. 연결된 노드의 prio만 직접 바꾸면 정렬 관계가 깨질 수 있으므로 제거·변경·재삽입 절차가 필요합니다.',
    [('문서와 전체 구성', 'SPDX, 저작권과 계보, 두 계층 ASCII 그림, 우선순위·복잡도·잠금 계약 뒤에 guard와 의존 헤더가 있습니다. 정적/동적 초기화, add/del/requeue 선언, 여섯 순회 매크로, 빈 상태 확인, first/last 포함 객체 매크로, next/prev, 첫·끝 노드 함수로 끝납니다.'),
     ('우선순위 방향', 'INT_MIN이 가장 높고 INT_MAX가 가장 낮습니다. node_list에서는 숫자 오름차순이며 의미상 높은 우선순위부터 나옵니다. 같은 숫자는 기본 삽입 순서 FIFO입니다. 문서의 descending-priority 표현을 정수 내림차순이라고 읽으면 반대가 됩니다.'),
     ('두 계층과 비용', 'prio_list에는 우선순위마다 대표 하나, node_list에는 모든 객체가 연결됩니다. 문서는 추가 O(K), 삭제 O(1), 우선순위 변경 O(K)를 설명합니다. K는 실제로 탐색할 서로 다른 우선순위 수에 연결됩니다. RT 우선순위 수준1..99 설명이 있어도 prio 필드 자체를 그 범위로 검사하거나 제한하는 코드는 아닙니다.'),
     ('초기화', 'PLIST_HEAD_INIT/HEAD는 node_list를 자기참조로 초기화합니다. PLIST_NODE_INIT은 prio와 두 링크를 설정합니다. 동적 head_init/node_init도 같은 역할입니다. prio_list가 자기참조라고 해서 객체가 전체 목록에서 빠졌다고 볼 수는 없습니다. node_empty는 node_list를 검사합니다.'),
     ('순회 종류', 'plist_for_each와 continue, safe는 plist_node 단위로 node_list를 순회합니다. entry/entry_continue/entry_safe는 포함 객체의 멤버.node_list를 사용합니다. continue는 현재 항목 다음부터, safe는 다음 위치를 임시 저장하여 현재 항목 제거를 돕습니다. 임의의 동시 삭제를 안전하게 만드는 잠금 기능은 아닙니다.'),
     ('첫·끝 접근의 전제', 'plist_first/last는 비어 있지 않은 헤드에서 가장 높은/낮은 우선순위 노드를 반환합니다. first_entry/last_entry는 포함 객체로 바꿉니다. CONFIG_DEBUG_PLIST면 빈 헤드 경고가 추가되지만 경고 후 유효한 객체가 자동 생성되지는 않습니다. next/prev는 sentinel 경계에서 사용자 객체가 존재하는지 자동 판정하지 않으므로 순회 경계를 지켜야 합니다.'),
     ('CS 연결', '안정된 동순위 순서, 우선순위 대표 압축, sentinel과 빈 상태, 정적/동적 초기화, 순회 중 제거의 안전 조건을 학습합니다. 내장 잠금이 없다는 원문 계약에 따라 호출 문맥의 동기화를 별도로 읽어야 합니다.')],
    [('prio값 -5와 20 중 먼저 나오는 것은?', '-5다', '20이다', '작은 숫자가 높은 우선순위입니다. 정렬된 node_list는 숫자 오름차순으로 순회합니다.'),
     ('prio_list가 자기참조이면 노드가 반드시 미등록인가?', '아니다. 등록 여부는 node_list로 확인한다', '그렇다. 두 링크는 항상 함께 비어 있다', '동순위 비대표 노드와 대표가 하나뿐인 링에서도 prio_list는 자기참조일 수 있습니다. plist_node_empty는 node_list를 검사합니다.'),
     ('DEBUG_PLIST의 빈 헤드 경고가 first 접근을 안전한 NULL 반환으로 바꾸는가?', '아니다. 비어 있지 않다는 호출 전제가 필요하다', '그렇다. 자동으로 NULL을 반환한다', '디버그 매크로는 WARN_ON 뒤에 원래 객체 변환을 수행합니다. 빈 입력을 허용하는 별도 반환 분기는 없습니다.')])

add('lib/plist.c', 'Plist 구현 전체: 양방향 대표 탐색·대표 승계·동순위 재배치',
    '삽입과 삭제에서 두 연결 계층의 불변식을 유지하는 구현 및 디버그 검사입니다.',
    '삽입은 우선순위 대표 링을 양쪽에서 탐색합니다. 대표를 삭제하면 같은 우선순위의 다음 노드가 필요한 대표 역할을 이어받습니다.',
    '이미 연결된 노드를 다시 삽입하거나 공유 상태를 잠금 없이 변경하지 않습니다. 디버그 경고와 테스트는 호출 계약을 대신하지 않습니다.',
    [('전체 파일', 'SPDX와 구현 계보, bug/plist 포함 뒤에 CONFIG_DEBUG_PLIST의 연결 검사 helper가 있습니다. 항상 존재하는 add/del/requeue 세 함수 뒤에 디버그 전용 상태 검사·재배치 검사·랜덤 테스트·시간 측정과 module_init이 이어집니다. 디버그가 꺼지면 plist_check_head는 빈 매크로입니다.'),
     ('구조 검사', 'plist_check_prev_next는 인접 포인터가 서로를 가리키는지 WARN으로 확인합니다. check_list는 원형 리스트를 한 바퀴 검사하고 check_head는 첫 노드의 대표 링과 전체 node_list를 확인합니다. WRITE_ONCE 사용은 이 검사를 임의의 동시 수정에도 안전하게 만드는 잠금이 아닙니다.'),
     ('삽입의 빈 경우와 선행 조건', 'plist_add는 노드가 전체 목록과 대표 링에 연결되어 있지 않은지 WARN_ON으로 점검합니다. 빈 헤드라면 바로 전체 node_list에 넣고 대표 링크는 자기참조 상태를 유지합니다. WARN 자체가 잘못된 입력을 안전하게 거부하는 조기 반환은 아닙니다.'),
     ('양방향 대표 탐색', 'first/iter는 첫 대표, last/reverse_iter는 대표 링의 마지막에서 시작합니다. 새 우선순위가 iter보다 작으면 그 앞을 선택합니다. reverse_iter 이상이면 그 대표 뒤 그룹 경계를 선택합니다. 그렇지 않으면 앞 커서는 next, 뒤 커서는 prev로 이동합니다. 모든 객체를 스캔하는 대신 서로 다른 우선순위 대표들을 탐색합니다.'),
     ('동순위 FIFO와 새 대표', 'prev가 없거나 prev->prio와 새 prio가 다르면 새 노드를 대표 링에 넣습니다. 같은 우선순위가 이미 있으면 대표 링크는 별도로 추가하지 않습니다. node_next로 선택한 다음 우선순위 그룹 앞 또는 헤드 끝에 node_list를 넣으므로 기존 동순위 객체들 뒤에 새 객체가 붙습니다.'),
     ('대표 삭제와 승계', '삭제할 노드의 prio_list가 비어 있지 않으면 다음 전체 노드를 확인합니다. 그 다음 노드의 prio_list가 비어 있으면 동일 그룹의 비대표라는 불변식을 이용해 대표 링에 끼워 넣습니다. 이후 원래 대표 링크를 list_del_init합니다. 모든 경우 마지막에 node_list를 제거·초기화합니다. 다음 노드의 prio를 직접 비교하지 않는 이유는 두 계층의 기존 불변식에 의존하기 때문입니다.'),
     ('대표 링 하나의 예외 모양', '우선순위가 한 종류뿐이면 대표 링은 자기참조여서 list_empty가 참입니다. 이때 대표 링크를 옮길 필요 없이 전체 node_list에서 첫 노드가 바뀌면 새 첫 노드가 그 단일 그룹의 접근점이 됩니다. 따라서 비어 있지 않은 prio_list 검사와 일반적인 대표라는 개념을 완전히 동일시하지 않습니다.'),
     ('동순위 재배치', 'plist_requeue는 빈 헤드나 미등록 노드에 BUG_ON을 수행합니다. 이미 전체 마지막이거나 다음 노드의 우선순위가 다르면 그룹의 끝이므로 그대로 반환합니다. 아니면 plist_del로 빼고 같은 우선순위의 나머지를 지나 다음 그룹 앞에 node_list만 다시 넣습니다. 기존 같은 우선순위 대표가 남기 때문에 새 대표 링크를 만들 필요가 없습니다. prio 자체는 바꾸지 않습니다.'),
     ('디버그 불변식 테스트', 'test_check는 예상 개수, 전체 우선순위 순서, 동순위 비대표의 빈 prio_list, 대표 링의 다음 연결과 닫힘을 BUG_ON으로 확인합니다. test_requeue는 재배치 뒤 다음 노드가 같은 우선순위가 아닌지 확인합니다. 241개 노드를 초기화한 뒤 local_clock 기반 상태와 곱셈·나머지 갱신으로1000회 추가/삭제를 선택하고 매 단계 검사합니다. 마지막에 모든 남은 노드를 삭제합니다.'),
     ('시간 측정과 검증 한계', '뒤의 worst case라는 이름의 테스트는0..240 우선순위 노드를 오름차순으로 삽입하며 ktime_get 차이를 누적해 출력합니다. 이 이름만으로 현재 양방향 탐색의 모든 입력 중 실제 최악이 증명되는 것은 아닙니다. 랜덤 검사는 시드와 제한된 반복에 의존하며 이 교재에서 해당 커널 init 테스트를 실행했다고 주장하지 않습니다.'),
     ('CS 연결', '계층별 불변식, 대표 승계, 안정된 우선순위 큐, 큐 내 공정한 재배치, 상수 시간 삭제와 탐색 삽입의 비용 차이, 검사와 증명의 범위를 학습합니다. requeue는 같은 그룹을 순회할 수 있어 모든 연산이 O(1)인 자료구조가 아닙니다.')],
    [('동순위 새 노드는 기존 동순위 그룹의 어디에 들어가는가?', '뒤에 들어가 FIFO 순서를 유지한다', '항상 맨 앞에 들어가 LIFO가 된다', '삽입 위치는 다음 우선순위 그룹의 앞 또는 전체 끝입니다. 같은 우선순위 대표 앞에 무조건 삽입하는 것이 아닙니다.'),
     ('대표 노드 삭제 시 같은 우선순위 노드가 남으면?', '필요한 경우 다음 노드가 대표 연결을 이어받는다', '남은 동순위 노드를 모두 삭제한다', '전체 다음 노드의 대표 링크가 비어 있으면 대표 링에 추가한 뒤 원래 대표를 제거합니다. 객체들은 그대로 남습니다.'),
     ('plist_requeue는 우선순위 숫자를 낮추는 함수인가?', '아니다. 같은 우선순위 그룹의 끝으로 이동한다', '그렇다. prio를1 감소시킨다', '함수 본문에 prio 변경은 없습니다. 동일 우선순위 객체들의 처리 순서를 조정합니다.'),
     ('worst case라는 테스트 이름만으로 최악 복잡도가 증명되는가?', '아니다. 특정 입력과 시간 측정일 뿐이다', '그렇다. 모든 입력을 자동 탐색한다', '이 코드는 정해진 오름차순 입력241개를 삽입합니다. 모든 가능한 순서나 분포의 실행 비용을 비교하지 않습니다.')])
